119	pub type Resolver = ResolverGeneric<FileSystemOs>;
120	
121	/// Non-generic core of the resolver holding the heavy resolution algorithm.
122	///
123	/// The filesystem is type-erased to `Arc<dyn FileSystem>` here so that the resolver
124	/// algorithm compiles exactly once, regardless of the concrete `Fs` type used by
125	/// [`ResolverGeneric`]. All public resolution methods live on this struct and are reachable
126	/// through [`ResolverGeneric`]'s [`Deref`](std::ops::Deref) implementation.
127	pub struct ResolverImpl {
128	    options: ResolveOptions,
129	    cache: Arc<Cache>,
130	    alias: CompiledAlias,
131	    fallback: CompiledAlias,
132	}
133	
134	/// Generic implementation of the resolver, can be configured by the [Cache] trait
135	pub struct ResolverGeneric<Fs> {
136	    inner: ResolverImpl,
137	    _marker: std::marker::PhantomData<Fs>,
138	}
139	
140	impl<Fs> std::ops::Deref for ResolverGeneric<Fs> {
141	    type Target = ResolverImpl;
142	
143	    fn deref(&self) -> &ResolverImpl {
144	        &self.inner
145	    }
146	}
