161	    #[must_use]
162	    pub fn new(options: ResolveOptions) -> Self {
163	        let options = options.sanitize();
164	        let alias = compile_alias(&options.alias);
165	        let fallback = compile_alias(&options.fallback);
166	        let fs = cfg_select! {
167	            feature = "yarn_pnp" => Fs::new(options.yarn_pnp),
168	            _ => Fs::new(),
169	        };
170	        let cache = Arc::new(Cache::new(Arc::new(fs) as Arc<dyn FileSystem>));
171	        let inner = ResolverImpl { options, cache, alias, fallback };
172	        Self { inner, _marker: std::marker::PhantomData }
173	    }
