184	    /// Clone the resolver using the same underlying cache.
185	    #[must_use]
186	    pub fn clone_with_options(&self, options: ResolveOptions) -> Self {
187	        let options = options.sanitize();
188	        let alias = compile_alias(&options.alias);
189	        let fallback = compile_alias(&options.fallback);
190	        let cache = cfg_select! {
191	            feature = "yarn_pnp" => {
192	                if options.yarn_pnp == self.inner.options.yarn_pnp {
193	                    Arc::clone(&self.inner.cache)
194	                } else {
195	                    Arc::new(Cache::new(Arc::new(Fs::new(options.yarn_pnp)) as Arc<dyn FileSystem>))
196	                }
197	            }
198	            _ => Arc::clone(&self.inner.cache),
199	        };
200	        let inner = ResolverImpl { options, cache, alias, fallback };
201	        Self { inner, _marker: std::marker::PhantomData }
202	    }
