//! TEMPORARY fs-call counting (not for commit).
#![allow(clippy::unwrap_used, clippy::print_stderr, missing_docs)]

use std::io;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use oxc_resolver::{FileMetadata, FileSystem, FileSystemOs, ResolveError};
use rustc_hash::FxHashMap;

static COUNTS: Mutex<Option<FxHashMap<(&'static str, PathBuf), u32>>> = Mutex::new(None);

pub fn hit(site: &'static str, path: impl AsRef<Path>) {
    let mut guard = COUNTS.lock().unwrap();
    *guard.get_or_insert_with(Default::default).entry((site, path.as_ref().to_owned())).or_default() += 1;
}

pub fn report() {
    let guard = COUNTS.lock().unwrap();
    let Some(map) = guard.as_ref() else { return };
    let mut by_site: FxHashMap<&str, (u64, u64, u32, PathBuf)> = FxHashMap::default();
    for ((site, path), n) in map {
        let e = by_site.entry(site).or_insert((0, 0, 0, PathBuf::new()));
        e.0 += u64::from(*n);
        e.1 += 1;
        if *n > e.2 {
            e.2 = *n;
            e.3 = path.clone();
        }
    }
    let mut sites: Vec<_> = by_site.into_iter().collect();
    sites.sort_by_key(|(s, _)| *s);
    let (mut total, mut distinct) = (0, 0);
    for (site, (calls, paths, max, max_path)) in sites {
        total += calls;
        distinct += paths;
        eprintln!("FSCOUNT {site:<28} calls {calls:>7} paths {paths:>7} max {max:>4} {}", max_path.display());
    }
    eprintln!("FSCOUNT TOTAL calls {total} site-paths {distinct}");
}

pub type Resolver = oxc_resolver::ResolverGeneric<CountingFs>;

pub struct CountingFs(FileSystemOs);

impl FileSystem for CountingFs {
    fn new() -> Self {
        Self(FileSystemOs::new())
    }
    fn read(&self, path: &Path) -> io::Result<Vec<u8>> {
        hit("oxc.read", path);
        self.0.read(path)
    }
    fn read_to_string(&self, path: &Path) -> io::Result<String> {
        hit("oxc.read_to_string", path);
        self.0.read_to_string(path)
    }
    fn metadata(&self, path: &Path) -> io::Result<FileMetadata> {
        hit("oxc.metadata", path);
        self.0.metadata(path)
    }
    fn symlink_metadata(&self, path: &Path) -> io::Result<FileMetadata> {
        hit("oxc.symlink_metadata", path);
        self.0.symlink_metadata(path)
    }
    fn read_link(&self, path: &Path) -> Result<PathBuf, ResolveError> {
        hit("oxc.read_link", path);
        self.0.read_link(path)
    }
    fn canonicalize(&self, path: &Path) -> io::Result<PathBuf> {
        hit("oxc.canonicalize", path);
        self.0.canonicalize(path)
    }
}

