/// The scope of `dir` if it or an ancestor has a mark. Memoised for every directory on the way up, so the files of
/// one tree probe each directory once rather than once per directory below it.
fn scope_within(&self, dir: &Utf8Path) -> Option<Box<str>> {
    if let Some(found) = self.scopes.get(dir.as_str()) {
        return found.clone();
    }
    let marks = ["package.json", "tsconfig.json", "jsconfig.json", "node_modules"];
    let has_mark = marks.iter().any(|mark| {
        crate::fscount::hit("dep.mark_exists", dir.join(mark));
        dir.join(mark).exists()
    });
    let scope = if has_mark { Some(Box::from(dir.as_str())) } else { dir.parent().and_then(|up| self.scope_within(up)) };
    self.scopes.insert(Box::from(dir.as_str()), scope.clone());
    scope
}

