import json, os, re, shutil, statistics, subprocess, sys, time
C = "/Users/gabe/.cache/caliper/corpora/repos/"
CORPORA = {
    "shadcn": C + "shadcn-ui/apps/v4",
    "mantine": C + "mantine/packages/@mantine/core/src",
    "antd": C + "ant-design/components",
    "spectrum": C + "react-spectrum/packages",
    "chakra": C + "chakra-ui/packages/react/src",
}
BINS = {"main": "/tmp/claude-501/fs/bin-main", "fix": "/tmp/claude-501/fs/bin-fix"}
RUNS = int(os.environ.get("RUNS", "5"))
names = sys.argv[1:] or list(CORPORA)


def load():
    return os.getloadavg()[0]


def once(bin_, src, cache_dir):
    args = ["/usr/bin/time", "-l", bin_, "extract", "--src", src, "--quiet", "--load-dependencies", "--json"]
    args += ["--cache-dir", cache_dir] if cache_dir else ["--no-cache"]
    t0 = time.monotonic()
    out = subprocess.run(args, capture_output=True, check=False)
    wall = time.monotonic() - t0
    err = out.stderr.decode(errors="replace")
    m = re.search(r"([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys", err)
    rss = int(re.search(r"(\d+)\s+maximum resident set size", err).group(1))
    d = json.loads(out.stdout)
    bad = any(x.get("code") == "SEMANTIC_BACKEND" and x.get("severity") != "info" for x in d.get("diagnostics", []))
    return dict(wall=float(m.group(1)), cpu=float(m.group(2)) + float(m.group(3)), sys=float(m.group(3)), rss=rss / 2**20, bad=bad)


results = {}
for name in names:
    src = CORPORA[name]
    for mode in ("cold", "cached"):
        caches = {}
        if mode == "cached":
            for b in BINS:
                caches[b] = f"/tmp/claude-501/fs/benchcache-{b}-{name}"
                shutil.rmtree(caches[b], ignore_errors=True)
                once(BINS[b], src, caches[b])
                once(BINS[b], src, caches[b])
        rows = {b: [] for b in BINS}
        loads = []
        for i in range(RUNS):
            order = list(BINS) if i % 2 == 0 else list(reversed(BINS))
            for b in order:
                loads.append(load())
                r = once(BINS[b], src, caches.get(b))
                if r["bad"]:
                    print("  dropped run (non-info SEMANTIC_BACKEND)", name, mode, b, flush=True)
                    continue
                rows[b].append(r)
        line = f"{name:9} {mode:6} load {min(loads):.1f}-{max(loads):.1f}"
        for b in BINS:
            rs = rows[b]
            med = {k: statistics.median(r[k] for r in rs) for k in ("wall", "cpu", "sys", "rss")}
            results[(name, mode, b)] = med
            line += f" | {b} n={len(rs)} wall {med['wall']:.2f} cpu {med['cpu']:.2f} sys {med['sys']:.2f} rss {med['rss']:.0f}"
        print(line, flush=True)

